import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"哀郢","description":"","frontmatter":{"title":"哀郢","date":"2026-11-24T00:00:00.000Z","seq":16,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"涉江","link":"/blogs/楚辞/涉江.html"},"next":{"text":"抽思","link":"/blogs/楚辞/抽思.html"}},"headers":[],"relativePath":"blogs/楚辞/哀郢.md","filePath":"blogs/楚辞/哀郢.md"}'),o={name:"blogs/楚辞/哀郢.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="哀郢" tabindex="-1">哀郢 <a class="header-anchor" href="#哀郢" aria-label="Permalink to &quot;哀郢&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　九章</p><div class="poem"><p class="poem-stanza">皇天之不纯命兮，何百姓之震愆？</p><p class="poem-stanza">民离散而相失兮，方仲春而东迁。</p><p class="poem-stanza">去故乡而就远兮，遵江夏以流亡。</p><p class="poem-stanza">出国门而轸怀兮，甲之鼂吾以行。</p><p class="poem-stanza">发郢都而去闾兮，怊荒忽其焉极？</p><p class="poem-stanza">楫齐扬以容与兮，哀见君而不再得。</p><p class="poem-stanza">望长楸而太息兮，涕淫淫其若霰。</p><p class="poem-stanza">过夏首而西浮兮，顾龙门而不见。</p><p class="poem-stanza">心婵媛而伤怀兮，眇不知其所蹠。</p><p class="poem-stanza">顺风波以从流兮，焉洋洋而为客。</p><p class="poem-stanza">凌阳侯之汜滥兮，忽翱翔之焉薄。</p><p class="poem-stanza">心絓结而不解兮，思蹇产而不释。</p><p class="poem-stanza">将运舟而下浮兮，上洞庭而下江。</p><p class="poem-stanza">去终古之所居兮，今逍遥而来东。</p><p class="poem-stanza">羌灵魂之欲归兮，何须臾而忘反。</p><p class="poem-stanza">背夏浦而西思兮，哀故都之日远。</p><p class="poem-stanza">登大坟以远望兮，聊以舒吾忧心。</p><p class="poem-stanza">哀州土之平乐兮，悲江介之遗风。</p><p class="poem-stanza">当陵阳之焉至兮，淼南渡之焉如？</p><p class="poem-stanza">曾不知夏之为丘兮，孰两东门之可芜？</p><p class="poem-stanza">心不怡之长久兮，忧与愁其相接。</p><p class="poem-stanza">惟郢路之辽远兮，江与夏之不可涉。</p><p class="poem-stanza">忽若不信兮，至今九年而不复。</p><p class="poem-stanza">惨郁郁而不通兮，蹇侘傺而含慼。</p><p class="poem-stanza">外承欢之汋约兮，谌荏弱而难持。</p><p class="poem-stanza">忠湛湛而愿进兮，妒被离而鄣之。</p><p class="poem-stanza">尧舜之抗行兮，瞭杳杳而薄天。</p><p class="poem-stanza">众谗人之嫉妒兮，被以不慈之伪名。</p><p class="poem-stanza">憎愠惀之修美兮，好夫人之慷慨。</p><p class="poem-stanza">众踥蹀而日进兮，美超远而逾迈。</p><p class="poem-stanza">乱曰：</p><p class="poem-stanza">曼余目以流观兮，冀一反之何时？</p><p class="poem-stanza">鸟飞反故乡兮，狐死必首丘。</p><p class="poem-stanza">信非吾罪而弃逐兮，何日夜而忘之？</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
